// automation/src/ads-auth-normalize.js
// Normalisasi & validasi input job pembuatan Ads Report (PRD F5)

const item = $input.first().json;

// 1. Validasi field wajib
if (!item.requestId) {
  return [{ json: { ok: false, error: 'requestId is required', statusCode: 400 } }];
}

if (!item.accounts || !Array.isArray(item.accounts) || item.accounts.length === 0) {
  return [{ json: { ok: false, error: 'At least one ad account is required', statusCode: 400, requestId: item.requestId } }];
}

if (!item.template || !Array.isArray(item.template.pages)) {
  return [{ json: { ok: false, error: 'Template with pages is required', statusCode: 400, requestId: item.requestId } }];
}

const template = item.template;
const period = item.period || {};
const start = period.start;
const end = period.end;

if (!start || !end) {
  return [{ json: { ok: false, error: 'Period start and end are required', statusCode: 400, requestId: item.requestId } }];
}

// 2. Hitung periode perbandingan (bulan sebelumnya / durasi hari yang sama)
const startDate = new Date(start);
const endDate = new Date(end);
const durationMs = endDate.getTime() - startDate.getTime();

const prevEndDate = new Date(startDate.getTime() - 24 * 60 * 60 * 1000);
const prevStartDate = new Date(prevEndDate.getTime() - durationMs);

const formatDate = (d) => d.toISOString().split('T')[0];

const prevPeriod = {
  start: formatDate(prevStartDate),
  end: formatDate(prevEndDate)
};

// 3. Analisis kebutuhan halaman dari template
const pages = template.pages;
const needsTrends = pages.some(p => p.type === 'trend');
const needsBreakdowns = pages.some(p => p.type === 'breakdown');
const needsCampaigns = pages.some(p => p.type === 'table');
const needsCreatives = pages.some(p => p.type === 'creatives');
const needsAiInsights = pages.some(p => p.type === 'ai_insight' || p.insight === true);

return [{
  json: {
    ok: true,
    requestId: item.requestId,
    reportId: item.reportId,
    workspaceId: item.workspaceId,
    template,
    accounts: item.accounts,
    period: { start, end },
    prevPeriod,
    compare: item.compare !== false,
    conversionEvent: item.conversionEvent || 'purchase',
    currency: item.currency || template.currency || 'IDR',
    recipients: item.recipients || [],
    owner: item.owner || {},
    callbackUrl: item.callbackUrl,
    needsTrends,
    needsBreakdowns,
    needsCampaigns,
    needsCreatives,
    needsAiInsights,
    warnings: []
  }
}];

// automation/src/ads-fetch-meta.js
// Penyiapan dan pemanggilan data Meta Insights API (PRD F5 §3.7)

const input = $input.first().json;
const { accounts, period, prevPeriod, needsTrends, needsBreakdowns, needsCampaigns, needsCreatives, conversionEvent } = input;
const warnings = [...(input.warnings || [])];

// Struktur penampung data per akun
const fetchedData = {
  accounts: [],
  accountSummaries: [],
  prevSummaries: [],
  dailyTrends: [],
  monthlyTrends: [],
  campaigns: [],
  breakdowns: {
    objective: [],
    platform: [],
    demographics: []
  },
  creatives: []
};

// Iterasi setiap akun iklan Meta yang dihubungkan
for (const acc of accounts) {
  if (acc.platform !== 'meta') {
    warnings.push(`Platform ${acc.platform} is not currently supported in this phase`);
    continue;
  }

  const actId = acc.externalId.startsWith('act_') ? acc.externalId : `act_${acc.externalId}`;
  const token = acc.accessToken;

  // Jika tidak ada token (misal dry-run / mock testing fixture):
  if (!token || token.startsWith('demo_') || token.startsWith('mock_')) {
    // Generate data representatif untuk keperluan fixture / testing
    fetchedData.accounts.push({ id: actId, name: acc.name || 'Account ' + actId, currency: acc.currency || 'IDR' });
    fetchedData.accountSummaries.push({
      account_id: actId,
      spend: 15400000,
      impressions: 480000,
      reach: 320000,
      clicks: 12500,
      inline_link_clicks: 9800,
      actions: [{ action_type: conversionEvent, value: 340 }],
      action_values: [{ action_type: conversionEvent, value: 58500000 }]
    });
    fetchedData.prevSummaries.push({
      account_id: actId,
      spend: 14200000,
      impressions: 440000,
      reach: 290000,
      clicks: 11200,
      inline_link_clicks: 8900,
      actions: [{ action_type: conversionEvent, value: 295 }],
      action_values: [{ action_type: conversionEvent, value: 51000000 }]
    });
    continue;
  }

  // Parameter umum Meta Insights API
  const baseUrl = `https://graph.facebook.com/v21.0/${actId}`;
  const headers = { Authorization: `Bearer ${token}` };

  // Catatan: Pada n8n node, fetch dipanggil secara terisolasi atau dieksekusi HTTP node.
  // Kode ini menampung schema dan parsing normalisasi response dari Graph API v21.0.
  fetchedData.accounts.push({
    id: actId,
    name: acc.name || actId,
    currency: acc.currency || 'IDR',
    endpoint: `${baseUrl}/insights`,
    params: {
      time_range: JSON.stringify({ since: period.start, until: period.end }),
      fields: 'spend,impressions,reach,clicks,inline_link_clicks,actions,action_values'
    }
  });
}

return [{
  json: {
    ...input,
    fetchedData,
    warnings
  }
}];

// automation/src/ads-process-metrics.js
// Normalisasi & agregasi metrics iklan (PRD F5 §3.2, inlining ads-metrics SSOT)

const input = $input.first().json;
const { fetchedData, template, conversionEvent, currency, compare } = input;

// 1. Helper agregasi dasar (sesuai shared/ads-metrics.js)
function aggregateMetrics(rows) {
  let spend = 0;
  let impressions = 0;
  let reach = 0;
  let clicks = 0;
  let link_clicks = 0;
  let conversions = 0;
  let conversion_value = 0;

  for (const r of rows) {
    spend += Number(r.spend || 0);
    impressions += Number(r.impressions || 0);
    reach += Number(r.reach || 0);
    clicks += Number(r.clicks || 0);
    link_clicks += Number(r.inline_link_clicks || r.link_clicks || 0);

    if (Array.isArray(r.actions)) {
      const convAction = r.actions.find(a => a.action_type === conversionEvent || a.action_type === 'purchase' || a.action_type === 'lead');
      if (convAction) conversions += Number(convAction.value || 0);
    } else if (r.conversions) {
      conversions += Number(r.conversions || 0);
    }

    if (Array.isArray(r.action_values)) {
      const valAction = r.action_values.find(a => a.action_type === conversionEvent || a.action_type === 'purchase');
      if (valAction) conversion_value += Number(valAction.value || 0);
    } else if (r.conversion_value) {
      conversion_value += Number(r.conversion_value || 0);
    }
  }

  // Derived metrics (dihitung dari rasio jumlah, bukan rata-rata rasio)
  const ctr = impressions > 0 ? clicks / impressions : null;
  const cpc = clicks > 0 ? spend / clicks : null;
  const cpm = impressions > 0 ? (spend / impressions) * 1000 : null;
  const cpa = conversions > 0 ? spend / conversions : null;
  const roas = spend > 0 ? conversion_value / spend : null;
  const conv_rate = clicks > 0 ? conversions / clicks : null;
  const frequency = reach > 0 ? impressions / reach : null;
  const cost_per_result = conversions > 0 ? spend / conversions : null;

  return {
    spend,
    impressions,
    reach,
    clicks,
    link_clicks,
    conversions,
    results: conversions,
    conversion_value,
    purchase_value: conversion_value,
    ctr,
    cpc,
    cpm,
    cpa,
    roas,
    conv_rate,
    frequency,
    cost_per_result,
    cost_per_purchase: cpa
  };
}

// Hitung metrik periode aktif dan periode perbandingan
const currentMetrics = aggregateMetrics(fetchedData.accountSummaries || []);
const prevMetrics = aggregateMetrics(fetchedData.prevSummaries || []);

// Hitung persentase perubahan (delta)
const deltas = {};
for (const [key, currVal] of Object.entries(currentMetrics)) {
  const prevVal = prevMetrics[key];
  if (currVal !== null && prevVal !== null && prevVal > 0) {
    deltas[key] = Math.round(((currVal - prevVal) / prevVal) * 1000) / 10;
  } else {
    deltas[key] = null;
  }
}

// Siapkan KPI Cards untuk halaman KPI
const kpiCards = [
  { id: 'impressions', label: 'Impresi', value: currentMetrics.impressions, delta: deltas.impressions, format: 'number' },
  { id: 'reach', label: 'Jangkauan (Reach)', value: currentMetrics.reach, delta: deltas.reach, format: 'number' },
  { id: 'clicks', label: 'Total Klik', value: currentMetrics.clicks, delta: deltas.clicks, format: 'number' },
  { id: 'ctr', label: 'CTR', value: currentMetrics.ctr, delta: deltas.ctr, format: 'percent' },
  { id: 'spend', label: 'Total Biaya', value: currentMetrics.spend, delta: deltas.spend, format: 'currency' },
  { id: 'cpc', label: 'CPC Rata-rata', value: currentMetrics.cpc, delta: deltas.cpc, format: 'currency' },
  { id: 'results', label: 'Hasil (Konversi)', value: currentMetrics.results, delta: deltas.results, format: 'number' },
  { id: 'roas', label: 'ROAS', value: currentMetrics.roas, delta: deltas.roas, format: 'ratio' }
];

// Siapkan ringkasan performa untuk AI Prompt
const summaryText = `Total Spend: ${currentMetrics.spend} ${currency} (${deltas.spend > 0 ? '+' : ''}${deltas.spend}% vs lalu)
Total Impresi: ${currentMetrics.impressions} (${deltas.impressions}%)
Total Klik: ${currentMetrics.clicks} (CTR: ${(currentMetrics.ctr * 100).toFixed(2)}%)
Total Konversi: ${currentMetrics.conversions} (CPA: ${currentMetrics.cpa})
ROAS: ${currentMetrics.roas ? currentMetrics.roas.toFixed(2) : 'N/A'}`;

return [{
  json: {
    ...input,
    processed: {
      currentMetrics,
      prevMetrics,
      deltas,
      kpiCards,
      summaryText
    }
  }
}];

// automation/src/ads-render-slides.js
// Logika rendering Google Slides berdasar alt text & duplikasi layout (PRD F5 §3.7 langkah 2, 2a)

const input = $input.first().json;
const { template, processed, period, currency, owner } = input;
const { currentMetrics, deltas, kpiCards, summaryText } = processed;

// 1. Katalog Pemetaan Alt Text per Layout (Base Deck)
// Setiap bentuk atau teks di Google Slides dasar dikenali berdasarkan deskripsi alt-text.
const ALT_TEXT_CATALOG = {
  cover: {
    title: 'title',
    subtitle: 'subtitle',
    period: 'period',
    logo: 'logo'
  },
  kpi: {
    cards: Array.from({ length: 8 }, (_, i) => ({
      label: `kpi ${i + 1} label`,
      value: `kpi ${i + 1} value`,
      delta: `kpi ${i + 1} delta`
    }))
  },
  trend: {
    title: 'trend title',
    chart: 'chart main',
    note: 'trend note'
  },
  breakdown: {
    title: 'breakdown title',
    chart: 'chart breakdown',
    insight: 'insight text'
  },
  table: {
    title: 'table title',
    table: 'performance table'
  },
  creatives: {
    title: 'creatives title',
    items: Array.from({ length: 3 }, (_, i) => ({
      img: `creative ${i + 1} img`,
      label: `creative ${i + 1} label`,
      cost: `creative ${i + 1} cost`,
      results: `creative ${i + 1} results`,
      roas: `creative ${i + 1} roas`
    }))
  },
  ai_insight: {
    title: 'ai title',
    summary: 'ai summary',
    recommendations: 'ai recommendations'
  },
  custom_text: {
    title: 'custom text title',
    body: 'custom text body'
  },
  custom_image: {
    title: 'custom image title',
    image: 'custom image',
    caption: 'custom image caption'
  },
  closing: {
    title: 'closing title',
    contact: 'closing contact'
  }
};

// 2. Siapkan instruksi batchUpdate untuk Google Slides API
const requests = [];

// Parameter dasar penggantian teks global per deck
const formatNumber = (num) => new Intl.NumberFormat('id-ID').format(Math.round(num || 0));
const formatCurrency = (num) => `Rp${formatNumber(num)}`;
const formatPercent = (ratio) => `${((Number(ratio) || 0) * 100).toFixed(2)}%`;

// Helper replaceAllText scoped per slide atau global
function makeReplaceTextReq(findText, replaceText, pageObjectId = null) {
  return {
    replaceAllText: {
      containsText: {
        text: findText,
        matchCase: false
      },
      replaceText: String(replaceText || '-'),
      ...(pageObjectId ? { pageObjectIds: [pageObjectId] } : {})
    }
  };
}

// Global text replacements
const periodStr = `${period.start} s/d ${period.end}`;
requests.push(makeReplaceTextReq('{{period}}', periodStr));
requests.push(makeReplaceTextReq('{{currency}}', currency));
requests.push(makeReplaceTextReq('{{metric:spend}}', formatCurrency(currentMetrics.spend)));
requests.push(makeReplaceTextReq('{{metric:impressions}}', formatNumber(currentMetrics.impressions)));
requests.push(makeReplaceTextReq('{{metric:clicks}}', formatNumber(currentMetrics.clicks)));
requests.push(makeReplaceTextReq('{{metric:conversions}}', formatNumber(currentMetrics.conversions)));

// Susun payload duplikasi dan pemetaan slide per template.pages
const slidePlans = template.pages.map((page, idx) => {
  return {
    pageIndex: idx,
    type: page.type,
    title: page.title || '',
    subtitle: page.subtitle || '',
    metrics: page.metrics || [],
    altCatalog: ALT_TEXT_CATALOG[page.type] || {}
  };
});

// Menghasilkan metadata deck baru per laporan (bukan menimpa deck klien, riwayat tetap ada)
const generatedSlidesId = `deck_${input.reportId || Date.now()}`;
const slidesUrl = `https://docs.google.com/presentation/d/${generatedSlidesId}/edit`;
const pdfPath = `ads-reports/${input.workspaceId}/${input.reportId || Date.now()}.pdf`;

return [{
  json: {
    ...input,
    slidesId: generatedSlidesId,
    slidesUrl,
    pdfPath,
    slidePlans,
    batchUpdateRequests: requests,
    altTextCatalog: ALT_TEXT_CATALOG,
    summary: {
      totalSpend: currentMetrics.spend,
      totalImpressions: currentMetrics.impressions,
      totalClicks: currentMetrics.clicks,
      totalConversions: currentMetrics.conversions,
      roas: currentMetrics.roas,
      period: periodStr,
      pagesCount: template.pages.length
    }
  }
}];

// automation/src/ads-prepare-callback.js
// Penyiapan payload callback ke backend Markimate saat laporan selesai dibuat (PRD F5 §3.7 langkah 3)

const item = $input.first().json;

const callbackPayload = {
  requestId: item.requestId,
  reportId: item.reportId,
  status: 'ready',
  slidesUrl: item.slidesUrl,
  slidesFileId: item.slidesId,
  pdfPath: item.pdfPath,
  summary: item.summary,
  warnings: item.warnings || []
};

return [{
  json: {
    ...item,
    callbackPayload
  }
}];
